<?php declare(strict_types=1);$changeOperation=$changeUi['operation'];$changeBlocked=$changeUi['blocked'];$isReview=$changeOperation['action']==='member-change-review';$changeConfirm=$isReview?'Ich habe den ursprünglichen Antrag mit den aktuellen Profildaten verglichen und bestätige die gewählte Entscheidung.':'Ich ziehe genau diesen noch offenen Änderungsantrag zurück.';?>
<section class="card" data-member-change-operation>
<?php if($changeBlocked):?><p role="status"><?=e($changeText('Die ursprünglichen Angaben bleiben gesperrt lesbar. Gespeicherten Stand vor einer weiteren Änderung getrennt prüfen.'))?></p><?php endif?>
<a class="btn btn-outline theme-secondary" target="_blank" rel="noopener" href="<?=e($changeUrl(['change'=>$changeOperation['id']]))?>"><?=e($changeText('Gespeicherten Antrag in neuem Fenster prüfen'))?></a>
<?php if($isReview&&$changeBlocked):?><label><?=e($changeText('Eigene ursprüngliche Rückmeldung'))?><textarea class="form-control" readonly rows="6" data-member-change-copy><?=(str_starts_with($changeOperation['note'],"\n")||str_starts_with($changeOperation['note'],"\r")?"\n":'').e($changeOperation['note'])?></textarea></label><?php endif?>
<fieldset <?=$changeBlocked?'disabled':''?>><form method="post" action="<?=e($changeUrl(['change'=>$changeOperation['id']]))?>" data-member-change-decision <?=$changeBlocked?'data-member-change-readonly':''?>>
<?=csrf().hidden('action',$changeOperation['action']).hidden('change',$changeOperation['id']).hidden('change_version',$_POST['change_version'])?>
<?php if($isReview):?><?=hidden('decision',$changeOperation['decision'])?><label><?=e($changeText('Rückmeldung an das Mitglied'))?><textarea class="form-control" name="decision_note" maxlength="2000" rows="6" <?=$changeOperation['decision']==='rejected'?'required':''?>><?=(str_starts_with($changeOperation['note'],"\n")||str_starts_with($changeOperation['note'],"\r")?"\n":'').e($changeOperation['note'])?></textarea></label><?php endif?>
<label class="check"><input class="check" type="checkbox" name="confirm_change" value="1" required><span><?=e($changeText($changeConfirm))?></span></label><button class="btn btn-solid theme-primary"><?=e($changeText($isReview?($changeOperation['decision']==='accepted'?'Geprüfte Angaben übernehmen':'Nicht übernehmen'):'Antrag zurückziehen'))?></button></form></fieldset></section>
<?php if($changeBlocked&&http_response_code()===503):require __DIR__.'/retry.php';endif?>
